'use client';

import { useQuery } from '@tanstack/react-query';
import { get } from '@/lib/api/client';
import { usePagedList } from '@/lib/api/hooks';

/** GET /v1/admin/* (platform super admins only; read-only). */

export interface AdminOverview {
  orgs: number;
  activeOrgs: number;
  users: number;
  verifiedUsers: number;
  calls: number;
  callsLast30Days: number;
}

export interface AdminOrg {
  id: string;
  name: string;
  slug: string;
  status: 'active' | 'suspended';
  createdAt: string;
  members: number;
  assistants: number;
  calls: number;
  callsLast30Days: number;
  lastCallAt: string | null;
}

export interface AdminOrgDetail extends Omit<AdminOrg, 'members'> {
  memberCount: number;
  members: { id: string; email: string; name: string; role: string; joinedAt: string; emailVerified: boolean; lastLoginAt: string | null }[];
}

export interface AdminUser {
  id: string;
  email: string;
  name: string;
  emailVerified: boolean;
  createdAt: string;
  lastLoginAt: string | null;
  platformRole: 'super_admin' | null;
  orgs: { id: string; name: string; role: string }[];
}

export function useAdminOverview() {
  return useQuery({ queryKey: ['admin', 'overview'], queryFn: ({ signal }) => get<AdminOverview>('/v1/admin/overview', undefined, signal) });
}

export function useAdminOrgs(q: string) {
  return usePagedList<AdminOrg>(['admin', 'orgs'], '/v1/admin/orgs', { q: q || undefined });
}

export function useAdminOrg(id: string) {
  return useQuery({ queryKey: ['admin', 'org', id], queryFn: ({ signal }) => get<AdminOrgDetail>(`/v1/admin/orgs/${id}`, undefined, signal) });
}

export function useAdminUsers(q: string) {
  return usePagedList<AdminUser>(['admin', 'users'], '/v1/admin/users', { q: q || undefined });
}
