'use client';

import { Building2, SearchX, Users } from 'lucide-react';
import Link from 'next/link';
import { useState } from 'react';
import { Badge } from '@/components/ui/badge';
import { Card, CardBody, CardHeader, Stat } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { LoadMore } from '@/components/ui/load-more';
import { PageBody, PageHeader } from '@/components/ui/page';
import { EmptyState, ErrorState, LoadingState, QueryState } from '@/components/ui/states';
import { Table, TBody, Td, Th, THead, Tr } from '@/components/ui/table';
import { formatDate, formatDateTime, formatNumber, humanize } from '@/lib/format';
import { useDebounced } from '@/lib/use-debounced';
import { useAdminOrg, useAdminOrgs, useAdminOverview, useAdminUsers } from './api';

const link = 'font-medium text-accent-text underline-offset-4 hover:underline';

export function AdminOverview() {
  const overview = useAdminOverview();
  return (
    <PageBody wide>
      <PageHeader title="Platform overview" description="Every organization and user on Voice of Octo. Read-only." />
      <QueryState query={overview} errorTitle="Could not load the overview">
        {(data) => (
          <dl className="grid grid-cols-2 gap-3 md:grid-cols-3">
            <Stat label="Organizations" value={formatNumber(data.orgs)} hint={`${formatNumber(data.activeOrgs)} active`} />
            <Stat label="Users" value={formatNumber(data.users)} hint={`${formatNumber(data.verifiedUsers)} with a confirmed email`} />
            <Stat label="Calls" value={formatNumber(data.calls)} hint={`${formatNumber(data.callsLast30Days)} in the last 30 days`} />
          </dl>
        )}
      </QueryState>
      <div className="mt-6 flex flex-wrap gap-3 text-sm">
        <Link href="/admin/orgs" className={link}>
          All organizations
        </Link>
        <Link href="/admin/users" className={link}>
          All users
        </Link>
      </div>
    </PageBody>
  );
}

function Search({ id, label, value, onChange, placeholder }: { id: string; label: string; value: string; onChange: (v: string) => void; placeholder: string }) {
  return (
    <div role="search" className="mb-5 max-w-md">
      <label htmlFor={id} className="sr-only">
        {label}
      </label>
      <Input id={id} type="search" value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} maxLength={100} />
    </div>
  );
}

export function AdminOrgList() {
  const [q, setQ] = useState('');
  const search = useDebounced(q.trim(), 300);
  const list = useAdminOrgs(search);
  return (
    <PageBody wide>
      <PageHeader title="Organizations" description="Customer organizations, newest first, with members, assistants and calls." />
      <Search id="org-search" label="Search organizations" value={q} onChange={setQ} placeholder="Search by name or slug" />
      {list.isPending ? (
        <LoadingState label="Loading organizations…" rows={5} />
      ) : list.isError ? (
        <ErrorState error={list.error} title="Could not load organizations" onRetry={() => void list.refetch()} />
      ) : list.items.length === 0 ? (
        search ? <EmptyState icon={<SearchX />} title="No organization matches" /> : <EmptyState icon={<Building2 />} title="No organizations yet" />
      ) : (
        <>
          <Table label="Organizations">
            <THead>
              <Tr>
                <Th>Organization</Th>
                <Th>Status</Th>
                <Th className="text-right">Members</Th>
                <Th className="hidden text-right md:table-cell">Assistants</Th>
                <Th className="text-right">Calls (30 days)</Th>
                <Th className="hidden lg:table-cell">Last call</Th>
                <Th className="hidden lg:table-cell">Created</Th>
              </Tr>
            </THead>
            <TBody>
              {list.items.map((org) => (
                <Tr key={org.id}>
                  <Td>
                    <Link href={`/admin/orgs/${org.id}`} className={link}>
                      {org.name}
                    </Link>
                    <div className="text-xs text-muted">{org.slug}</div>
                  </Td>
                  <Td>
                    <Badge tone={org.status === 'active' ? 'success' : 'warning'}>{humanize(org.status)}</Badge>
                  </Td>
                  <Td className="text-right tabular-nums">{formatNumber(org.members)}</Td>
                  <Td className="hidden text-right tabular-nums md:table-cell">{formatNumber(org.assistants)}</Td>
                  <Td className="text-right tabular-nums">
                    {formatNumber(org.callsLast30Days)} <span className="text-muted">/ {formatNumber(org.calls)}</span>
                  </Td>
                  <Td className="hidden text-muted lg:table-cell">{org.lastCallAt ? formatDateTime(org.lastCallAt) : '—'}</Td>
                  <Td className="hidden text-muted lg:table-cell">{formatDate(org.createdAt)}</Td>
                </Tr>
              ))}
            </TBody>
          </Table>
          <LoadMore count={list.items.length} noun="organization" hasNextPage={list.hasNextPage} isFetchingNextPage={list.isFetchingNextPage} fetchNextPage={list.fetchNextPage} />
        </>
      )}
    </PageBody>
  );
}

export function AdminOrgDetail({ id }: { id: string }) {
  const org = useAdminOrg(id);
  return (
    <PageBody wide>
      <QueryState query={org} errorTitle="Could not load this organization" loading={<LoadingState label="Loading organization…" rows={4} />}>
        {(data) => (
          <>
            <PageHeader
              breadcrumb={
                <Link href="/admin/orgs" className="underline-offset-4 hover:underline">
                  Organizations
                </Link>
              }
              title={data.name}
              description={
                <span className="flex flex-wrap items-center gap-2">
                  <Badge tone={data.status === 'active' ? 'success' : 'warning'}>{humanize(data.status)}</Badge>
                  <span>{data.slug}</span>
                  <span>· created {formatDate(data.createdAt)}</span>
                </span>
              }
            />
            <dl className="mb-6 grid grid-cols-2 gap-3 md:grid-cols-4">
              <Stat label="Members" value={formatNumber(data.memberCount)} />
              <Stat label="Assistants" value={formatNumber(data.assistants)} />
              <Stat label="Calls" value={formatNumber(data.calls)} hint={`${formatNumber(data.callsLast30Days)} in the last 30 days`} />
              <Stat label="Last call" value={<span className="text-base">{data.lastCallAt ? formatDateTime(data.lastCallAt) : '—'}</span>} />
            </dl>
            <Card>
              <CardHeader title="Members" />
              <CardBody>
                <Table label="Members">
                  <THead>
                    <Tr>
                      <Th>Name</Th>
                      <Th>Email</Th>
                      <Th>Role</Th>
                      <Th className="hidden md:table-cell">Last sign-in</Th>
                    </Tr>
                  </THead>
                  <TBody>
                    {data.members.map((m) => (
                      <Tr key={m.id}>
                        <Td>{m.name}</Td>
                        <Td className="break-all">
                          {m.email}
                          {!m.emailVerified ? <Badge tone="warning" className="ml-2">Not confirmed</Badge> : null}
                        </Td>
                        <Td className="capitalize">{m.role}</Td>
                        <Td className="hidden text-muted md:table-cell">{m.lastLoginAt ? formatDateTime(m.lastLoginAt) : 'Never'}</Td>
                      </Tr>
                    ))}
                  </TBody>
                </Table>
              </CardBody>
            </Card>
          </>
        )}
      </QueryState>
    </PageBody>
  );
}

export function AdminUserList() {
  const [q, setQ] = useState('');
  const search = useDebounced(q.trim(), 300);
  const list = useAdminUsers(search);
  return (
    <PageBody wide>
      <PageHeader title="Users" description="Everyone with an account, newest first, with their organizations and roles." />
      <Search id="user-search" label="Search users" value={q} onChange={setQ} placeholder="Search by email or name" />
      {list.isPending ? (
        <LoadingState label="Loading users…" rows={5} />
      ) : list.isError ? (
        <ErrorState error={list.error} title="Could not load users" onRetry={() => void list.refetch()} />
      ) : list.items.length === 0 ? (
        search ? <EmptyState icon={<SearchX />} title="No user matches" /> : <EmptyState icon={<Users />} title="No users yet" />
      ) : (
        <>
          <Table label="Users">
            <THead>
              <Tr>
                <Th>User</Th>
                <Th>Organizations</Th>
                <Th className="hidden md:table-cell">Last sign-in</Th>
                <Th className="hidden lg:table-cell">Joined</Th>
              </Tr>
            </THead>
            <TBody>
              {list.items.map((user) => (
                <Tr key={user.id}>
                  <Td>
                    <div className="font-medium text-text">{user.name}</div>
                    <div className="text-xs break-all text-muted">{user.email}</div>
                    <div className="mt-1 flex flex-wrap gap-1">
                      {user.platformRole === 'super_admin' ? <Badge tone="accent">Super admin</Badge> : null}
                      {!user.emailVerified ? <Badge tone="warning">Not confirmed</Badge> : null}
                    </div>
                  </Td>
                  <Td>
                    {user.orgs.length === 0 ? (
                      <span className="text-muted">—</span>
                    ) : (
                      <ul className="flex flex-col gap-0.5">
                        {user.orgs.map((org) => (
                          <li key={org.id}>
                            <Link href={`/admin/orgs/${org.id}`} className={link}>
                              {org.name}
                            </Link>{' '}
                            <span className="text-xs text-muted capitalize">{org.role}</span>
                          </li>
                        ))}
                      </ul>
                    )}
                  </Td>
                  <Td className="hidden text-muted md:table-cell">{user.lastLoginAt ? formatDateTime(user.lastLoginAt) : 'Never'}</Td>
                  <Td className="hidden text-muted lg:table-cell">{formatDate(user.createdAt)}</Td>
                </Tr>
              ))}
            </TBody>
          </Table>
          <LoadMore count={list.items.length} noun="user" hasNextPage={list.hasNextPage} isFetchingNextPage={list.isFetchingNextPage} fetchNextPage={list.fetchNextPage} />
        </>
      )}
    </PageBody>
  );
}
